/* =============================================================
   MMG AI Assistant — Embed Loader (1-linie)
   v2.1.0 — Structură producție /mmg-ai/

   Usage pe site-ul MMG (pe orice pagină HTML — Homepage, Servicii, Contact, Despre noi):

   <script
     src="https://mmgaccounting.ro/mmg-ai/embed.min.js"
     data-mmg-leads-endpoint="https://api.mmgaccounting.ro/leads"
     async>
   </script>

   Sau, pentru testare locală / staging:

   <script
     src="/mmg-ai/embed.min.js"
     async>
   </script>

   Atribute suportate (toate opționale):
   - data-mmg-base             — URL-ul de bază al folderului /mmg-ai/ (default: dedus din src-ul scriptului)
   - data-mmg-leads-endpoint   — URL backend unde se POST-ează lead-urile (JSON). Recomandat pentru CRM/email/Sheets.
   - data-mmg-knowledge-url    — URL alternativ pentru mmg-knowledge.json
   - data-mmg-auto-open        — milisecunde până la auto-deschidere (ex: "5000" → 5s). Default: 0 (manual)
   - data-mmg-whatsapp         — suprascrie numărul de WhatsApp din JSON (ex: "40712345678")
   - data-mmg-phone            — suprascrie telefonul afișat (ex: "+40 21 123 45 67")
   - data-mmg-email            — suprascrie email-ul afișat (ex: "contact@mmgaccounting.ro")
   - data-mmg-fab-bottom       — offset vertical FAB în px (ex: "88" dacă WhatsApp e la bottom:20px). Default: "88"
   ============================================================= */
(function () {
  "use strict";

  if (window.__MMG_EMBED_LOADED__) return;
  window.__MMG_EMBED_LOADED__ = true;

  // 1. Găsește tag-ul curent
  var scripts = document.getElementsByTagName("script");
  var currentScript = scripts[scripts.length - 1];
  // Dacă currentScript nu e embed (ex: a fost inclus dinamic), caută-l explicit
  if (!currentScript || !/embed\.min\.js$/.test(currentScript.src || "")) {
    for (var i = 0; i < scripts.length; i++) {
      if (/embed\.min\.js$/.test(scripts[i].src || "")) {
        currentScript = scripts[i];
        break;
      }
    }
  }
  if (!currentScript) {
    console.warn("[MMG AI] Embed script nu a fost găsit");
    return;
  }

  // 2. Citește atributele data-*
  var base = currentScript.getAttribute("data-mmg-base") || "";
  // Dacă data-mmg-base lipsește, deduce din src-ul scriptului (ex: "/mmg-ai/embed.min.js" → "/mmg-ai/")
  if (!base) {
    var src = currentScript.src || "";
    if (src) {
      try {
        var parsed = new URL(src, window.location.href);
        // Îndepărtează "embed.min.js" de la final
        base = parsed.pathname.replace(/embed\.min\.js.*$/, "");
        // Dacă nu am obținut nimic (ex: pathname-era doar "/embed.min.js"), folosim "/"
        if (!base) base = "/";
      } catch (e) {
        base = "";
      }
    }
  }
  // Asigură trailing slash
  if (base && base.charAt(base.length - 1) !== "/") base += "/";

  var leadsEndpoint = currentScript.getAttribute("data-mmg-leads-endpoint") || null;
  var knowledgeUrl = currentScript.getAttribute("data-mmg-knowledge-url") ||
                     (base + "mmg-knowledge.json");
  var autoOpenAttr = currentScript.getAttribute("data-mmg-auto-open");
  var autoOpenDelay = autoOpenAttr ? parseInt(autoOpenAttr, 10) || 0 : 0;
  var overrideWhatsapp = currentScript.getAttribute("data-mmg-whatsapp");
  var overridePhone = currentScript.getAttribute("data-mmg-phone");
  var overrideEmail = currentScript.getAttribute("data-mmg-email");

  // Expune la global pentru mmg-ai.js
  window.__MMG_BASE__ = base;
  window.__MMG_LEADS_ENDPOINT__ = leadsEndpoint;

  // Override FAB bottom offset (pentru a nu se suprapune cu WhatsApp-ul site-ului)
  var fabBottomAttr = currentScript.getAttribute("data-mmg-fab-bottom");
  if (fabBottomAttr) {
    window.__MMG_FAB_BOTTOM__ = parseInt(fabBottomAttr, 10);
  }

  // 3. Helper: încarcă CSS
  function loadCSS(href, cb) {
    var link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = href;
    link.crossOrigin = "anonymous";
    link.onload = function () { if (cb) cb(); };
    link.onerror = function () { console.warn("[MMG AI] CSS nu a putut fi încărcat: " + href); };
    document.head.appendChild(link);
  }

  // 4. Helper: încarcă JS
  function loadJS(src, cb) {
    var s = document.createElement("script");
    s.src = src;
    s.async = true;
    s.crossOrigin = "anonymous";
    s.onload = function () { if (cb) cb(); };
    s.onerror = function () { console.warn("[MMG AI] JS nu a putut fi încărcat: " + src); };
    document.body.appendChild(s);
  }

  // 5. Helper: prefetch JSON și suprascrie overrides
  function prefetchKnowledge(url, cb) {
    fetch(url, { cache: "no-cache" })
      .then(function (r) {
        if (!r.ok) throw new Error("HTTP " + r.status);
        return r.json();
      })
      .then(function (data) {
        // Aplicăm overrides
        if (overrideWhatsapp) data.company.whatsapp = overrideWhatsapp;
        if (overridePhone) data.company.phone = overridePhone;
        if (overrideEmail) data.company.email = overrideEmail;
        window.__MMG_KNOWLEDGE__ = data;
        cb(data);
      })
      .catch(function (e) {
        console.warn("[MMG AI] Knowledge prefetch a eșuat:", e.message);
        cb(null);
      });
  }

  // 6. Bootstrap
  function bootstrap() {
    if (autoOpenDelay > 0 && window.MMGAI) {
      window.MMGAI.configure({ autoOpenDelay: autoOpenDelay });
    }
    // Re-inițializează dacă a fost încărcat înainte de a fi fost gata JSON-ul
    if (window.MMGAI && window.MMGAI.getKnowledge && !window.MMGAI.getKnowledge()) {
      // mmg-ai.js a încercat deja să încarce JSON-ul; nimic de făcut
    }
    // Eveniment gata
    window.dispatchEvent(new CustomEvent("mmg:ready", {
      detail: { base: base, knowledge: window.__MMG_KNOWLEDGE__ }
    }));
  }

  // 7. Pornește încărcarea (structură plată — toate fișierele în /mmg-ai/)
  function start() {
    loadCSS(base + "mmg-ai.css", function () {
      prefetchKnowledge(knowledgeUrl, function () {
        loadJS(base + "mmg-ai.js", bootstrap);
      });
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", start);
  } else {
    start();
  }

})();
